"""Official nationwide legal-dong dictionary; no API credentials or price fields.

The embedded payload is the official code.go.kr full TSV, compressed for the
portable Python deliverable. Refresh validates the whole download before swap.
"""
from __future__ import annotations
import base64
import copy
import datetime as dt
import hashlib
import io
import re
import threading
import urllib.parse
import urllib.request
import zipfile
import zlib

SOURCE_URL = "https://www.code.go.kr/stdcode/regCodeL.do"
DOWNLOAD_URL = "https://www.code.go.kr/etc/codeFullDown.do"
EMBEDDED_AT = "2026-09-27T10:53:29.186296+00:00"
EMBEDDED_SHA256 = "71f034a8542056b6ae3f70224fc0f70d377127a5d220d959476453ca5b5ca4d7"
EMBEDDED = ""
ALIASES = {"서울":"서울특별시","서울시":"서울특별시","부산":"부산광역시","대구":"대구광역시","인천":"인천광역시","광주":"광주광역시","대전":"대전광역시","울산":"울산광역시","세종":"세종특별자치시","경기":"경기도","강원":"강원특별자치도","강원도":"강원특별자치도","충북":"충청북도","충남":"충청남도","전북":"전북특별자치도","전라북도":"전북특별자치도","전남":"전라남도","경북":"경상북도","경남":"경상남도","제주":"제주특별자치도","제주도":"제주특별자치도"}


def parse_dictionary(value, nationwide=True):
    lines=value.lstrip("\ufeff").splitlines()
    if not lines or lines[0].split("\t") != ["법정동코드","법정동명","폐지여부"]:
        raise ValueError("공식 법정동 목록의 컬럼이 변경되었습니다. 이전 목록을 유지합니다.")
    result=[];seen=set()
    for line in lines[1:]:
        if not line.strip():continue
        parts=line.split("\t")
        if len(parts)!=3:raise ValueError("법정동 목록에 형식이 다른 행이 있습니다.")
        code,name,state=(s.strip() for s in parts)
        if not re.fullmatch(r"\d{10}",code) or code in seen or not name or state not in ("존재","폐지"):
            raise ValueError("법정동 목록의 코드·명칭·폐지 상태를 검증하지 못했습니다.")
        seen.add(code)
        level="sido" if code[2:]=="00000000" else "sgg" if code[5:]=="00000" else "dong" if code[8:]=="00" else "ri"
        parent=None if level=="sido" else code[:2]+"00000000" if level=="sgg" else code[:5]+"00000" if level=="dong" else code[:8]+"00"
        result.append({"code":code,"name":name,"label":name,"level":level,"parentCode":parent,"sggCode":code[:5] if level!="sido" else None,"legalDongCode":code if level in ("dong","ri") else None,"active":state=="존재","current":state=="존재","abolitionStatus":state})
    # The official current list can change with administrative reorganisations.
    # Do not pin province count or remap abolished codes to an invented successor.
    if nationwide and (len(result)<30000 or not 10<=sum(r["active"] and r["level"]=="sido" for r in result)<=30):
        raise ValueError("전국 법정동 목록의 행수·시도 수 검증에 실패했습니다. 이전 목록을 유지합니다.")
    return result


def download_dictionary():
    body=urllib.parse.urlencode({"codeseId":"법정동코드"}).encode()
    request=urllib.request.Request(DOWNLOAD_URL,data=body,headers={"User-Agent":"PF-Study/1.0","Referer":SOURCE_URL})
    with urllib.request.urlopen(request,timeout=30) as response:
        raw=response.read(8_000_001)
    if len(raw)>8_000_000:raise ValueError("공식 지역 목록의 다운로드 크기 제한을 초과했습니다.")
    archive=zipfile.ZipFile(io.BytesIO(raw))
    files=[i for i in archive.infolist() if not i.is_dir()]
    if len(files)!=1 or files[0].file_size>20_000_000:raise ValueError("공식 지역 압축파일 구성이 변경되었습니다.")
    return archive.read(files[0]).decode("cp949")


class RegionCatalog:
    def __init__(self):
        source=zlib.decompress(base64.b64decode(EMBEDDED)).decode("utf-8")
        self.rows=parse_dictionary(source)
        self.downloaded_at=EMBEDDED_AT
        self.sha256=EMBEDDED_SHA256
        self.lock=threading.RLock()
        self.warning=None

    def refresh(self,download=None):
        try:
            source=(download or download_dictionary)()
            rows=parse_dictionary(source)
        except Exception:
            with self.lock:self.warning="공식 지역 목록 갱신 실패: 마지막으로 확인한 목록을 사용합니다."
            return False
        with self.lock:
            self.rows=rows;self.downloaded_at=dt.datetime.now(dt.timezone.utc).isoformat()
            self.sha256=hashlib.sha256(source.encode()).hexdigest();self.warning=None
        return True

    def search(self,q="",parent="",level="all",current=True,limit=40,refresh=False):
        if refresh:self.refresh()
        if level=="emd":level="dong"
        if level not in ("all","sido","sgg","dong","ri"):raise ValueError("지역 검색 단계가 올바르지 않습니다.")
        if parent and not re.fullmatch(r"\d{2}|\d{5}|\d{10}",parent):raise ValueError("상위 지역 코드가 올바르지 않습니다.")
        terms=str(q).strip().split()
        if terms:
            expanded=ALIASES.get(terms[0],terms[0])
            if not current or any(r["active"] and r["name"]==expanded for r in self.rows):terms[0]=expanded
        with self.lock:
            candidates=[r for r in self.rows if (not current or r["active"]) and (level=="all" or r["level"]==level)]
            if parent:
                prefix=parent[:2] if len(parent)==10 and parent[2:]=="00000000" else parent[:5] if len(parent)==10 and parent[5:]=="00000" else parent[:8] if len(parent)==10 and parent[8:]=="00" else parent
                candidates=[r for r in candidates if r["code"].startswith(prefix) and r["code"]!=parent]
            candidates=[r for r in candidates if all(term in r["name"] for term in terms)]
            candidates.sort(key=lambda r:(not r["active"],len(r["name"].split()),r["name"],r["code"]))
            return {"items":copy.deepcopy(candidates[:max(1,min(100,int(limit)))]),"totalMatches":len(candidates),"sourceUrl":SOURCE_URL,"downloadUrl":DOWNLOAD_URL,"downloadedAt":self.downloaded_at,"referenceDate":self.downloaded_at[:10],"referenceDateMeaning":"목록 다운로드 시점; 개별 행의 효력 발생일은 제공되지 않음","sha256":self.sha256,"status":"last_known" if self.warning else "verified_download","warnings":[self.warning] if self.warning else [],"totalRows":len(self.rows)}
